// fgets-like reader: fills up to num-1 chars, NUL-terminates, returns str or NULL on EOF/error
ini_reader rdr = +[](char* str, int num, void* stream) -> char* {
    if (!str || num <= 0) return nullptr;
    ReaderState *s = static_cast<ReaderState*>(stream);
    if (!s || s->pos >= s->size) return nullptr;
    size_t max_copy = (size_t)num - 1;
    size_t i = 0;
    while (i < max_copy && s->pos < s->size) {
        char c = s->buf[s->pos++];
        str[i++] = c;
        if (c == '\n') break; // stop at newline like fgets
    }
    str[i] = '\0';
    return str;
};
// Simple handler that always accepts
