// State passed to handler to track calls and alternate accept/reject without using FUZZ_PARAM inside lambda
struct HandlerState { int calls; int flip; } state{0, (int)(*FUZZ_PARAM(unsigned int) & 1u)};

// Handler matching default inih signature (no lineno). Avoids FUZZ_PARAM usage inside the lambda.
ini_handler cb = +[](void* user, const char* section, const char* name, const char* value) -> int {
    HandlerState *st = static_cast<HandlerState*>(user);
    // Enforce non-null pointers as expected by parser; rejecting if violated exercises error path
    if (!section || !name || !value) { return 0; }
    if (st) {
        st->calls++;
        // Allowed by API: value may be modified during the call (cast away const)
        if (value[0] != '\0') { const_cast<char*>(value)[0] ^= 0x01; }
        // Alternate accept/reject deterministically using state, to cover both paths
        int accept = st->flip;
        st->flip ^= 1;
        return accept ? 1 : 0;
    }
    // If no state, default to accept
    return 1;
};

// Invoke parser; user pointer is passed through to handler unchanged by the API
int rc = ini_parse(path, cb, &state);

// Validate documented return codes: 0 success, >0 first error line, -1 open error, -2 OOM (optional)
if (!(rc == 0 || rc > 0 || rc == -1 || rc == -2)) { FUZZ_BAIL(); }

